import copy

# Original pattern
orig = [
    [9, 9, 8, 8, 8],
    [9, 9, 0, 0, 0],
    [8, 8, 0, 8, 8],
    [8, 0, 0, 0, 8]
]

# Apply 90° CW rotation formula: new[i][j] = old[H-1-j][i] where H=4
H, W = 4, 5
rot = [[0]*4 for _ in range(5)]

print(f"Original {H}x{W} pattern:")
for row in orig:
    print(row)

print(f"\nRotated 90° CW to {W}x{H}:")
for i in range(5):
    for j in range(4):
        rot[i][j] = orig[H-1-j][i]
    print(rot[i])

# Verify by checking where 9s end up
print(f"\n9s positions in original:")
for i in range(4):
    for j in range(5):
        if orig[i][j] == 9:
            print(f"  ({i},{j})")

print(f"\n9s positions in rotated:")
for i in range(5):
    for j in range(4):
        if rot[i][j] == 9:
            print(f"  ({i},{j})")
